    'free-review':()=>{captureFree();if(!free.title.trim()||!free.prompt.trim())return toast('Donnez un nom et un prompt à cette fabrication.');free.rules=free.universe?(free.rules??st().game.style):'';free.reviewEditing=false;freeReview();},
    'free-back':()=>{captureFree();freeForm();},'free-send':()=>{captureFree();const blocked=freeBlocked();if(blocked)return toast(blocked);if(free.reviewEditing)return toast('Terminez les modifications avant de lancer.');for(let i=0;i<free.count;i++)st().freeJobs.push({...clone(free),title:free.title+(free.type==='Vidéo'?' · clip '+(i+1):''),count:1,batchCount:free.count,batchEstimate:free.estimate,consumption:{amount:free.engine.startsWith('API')&&Number.isFinite(free.cost)?free.cost:null,unit:free.engine.startsWith('API')?'USD':null},cost:free.cost?free.cost.toFixed(2)+' $ fictifs par appel':'0 $ fournisseur · temps local non mesuré',id:id(),status:'En attente'});save();$('#dialog').close();api.navigate('jobs');},
    'free-job-read':el=>{const j=st().freeJobs.find(j=>j.id===el.dataset.id);modal('Paramètres conservés',`<h3>${esc(j.title)}</h3><p><strong>${esc(j.model||j.engine)}</strong> · ${esc(j.cost)}</p><p>${esc(j.size)} · graine ${j.seed}${j.type==='Vidéo'?' · '+(j.ratio||'1:1')+' · '+j.duration+' s · 1 clip':''}${j.type==='3D'?' · détail '+(j.topology||'Standard'):''}</p>${j.batchCount>1?'<p class="small">Issu d’un envoi de '+j.batchCount+' clips · '+esc(j.batchEstimate||'')+'</p>':''}${field('Consigne envoyée',`<textarea readonly>${esc(j.prompt)}</textarea>`)}${field('Univers envoyé',`<textarea readonly>${esc(j.rules||'Univers désactivé')}</textarea>`)}<h3>${j.refs.length} références conservées</h3><div class="review-references">${j.refs.map((r,i)=>`<article><img src="${esc(r.image||r.url)}" alt="${esc(r.name)}"><strong>${esc(r.name)}</strong><small>${j.type==='Vidéo'&&i===0?'Image de départ obligatoire':'Référence d’apparence'}</small></article>`).join('')}</div><p class="demo">Envoi simulé ; aucun fournisseur n’a été appelé.</p>`);},
    'free-finish':el=>{const j=st().freeJobs.find(j=>j.id===el.dataset.id);if(!j||j.status!=='En attente')return;const r=api.result(j.title,j.type==='Vidéo');Object.assign(r,{type:j.type,request:clone(j),provenance:'Fabrication libre simulée · '+j.engine});st().media.push(r);j.status='Terminé';j.resultId=r.id;if(j.canvas)onCanvas({r,type:r.type});save();render();},
    'media-open':el=>mediaOpen(el.dataset.id),'media-canvas':el=>{const x=item(el.dataset.id);if(x)onCanvas(x);},
