    'attach-save':el=>{const x=item(el.dataset.id),s=st().subjects.find(s=>s.id===val('attach-subject'));if(!x||!s)return;s.results.push({...clone(x.r),type:undefined});st().media=st().media.filter(r=>r.id!==x.r.id);save();$('#dialog').close();api.openSubject(s.id,'images');},
    'model-renders':el=>{modal('Rendus depuis une source 3D',`<p>Source 3D fictive conservée. Choisissez le personnage qui recevra le rig et les rendus de démonstration.</p>${field('Personnage',`<select name="model-subject">${st().subjects.map(s=>`<option value="${s.id}">${esc(s.name)}</option>`).join('')}</select>`)}`,button('Ouvrir la préparation 3D','model-target',`data-id="${el.dataset.id}"`));},
    'model-target':el=>{const s=st().subjects.find(s=>s.id===val('model-subject'));s.model3d={id:el.dataset.id,rig:false,renders:0};save();$('#dialog').close();api.openSubject(s.id);api.navigate('source');},
